'use strict';

const { test } = require('node:test');
const assert = require('node:assert/strict');
const fs = require('node:fs');
const path = require('node:path');
const { manualClock } = require('../src/clock');
const { loadConfig, ConfigError } = require('../src/config');
const { TicketStore } = require('../src/store');
const { createPersistence, fromDocument, toDocument } = require('../src/persistence');
const { ticketBody, withService } = require('./helpers');
const { DEFAULT_HOURS } = require('../src/tickets/due');

function dataFile(t) {
  const dir = fs.mkdtempSync(path.join(__dirname, 'due-data-'));
  t.after(() => fs.rmSync(dir, { recursive: true, force: true }));
  return path.join(dir, 'tickets.json');
}

test('due configuration has defaults, explicit enablement and validated response hours', () => {
  assert.equal(loadConfig({}).dueTimes, false);
  assert.equal(loadConfig({ DUE_TIMES: 'true' }).dueTimes, false);
  assert.deepEqual(loadConfig({}).dueHours, DEFAULT_HOURS);
  const configured = loadConfig({ DUE_TIMES: 'on', DUE_HOURS_HIGH: '8' });
  assert.equal(configured.dueTimes, true);
  assert.equal(configured.dueHours.high, 8);
  for (const value of ['0', '-1', '1.5', 'later', '999999999999']) {
    assert.throws(() => loadConfig({ DUE_HOURS_HIGH: value }), error => error instanceof ConfigError && /DUE_HOURS_HIGH/.test(error.message));
  }
});

test('each priority gets its response hours and priority edits preserve due on every API response', async () => {
  const clock = manualClock();
  await withService({ clock, dueTimes: true }, async api => {
    for (const [priority, hours] of Object.entries(DEFAULT_HOURS)) {
      const ticket = (await api.post('/tickets', ticketBody({ priority }))).body;
      assert.equal(ticket.due, new Date(clock.now().getTime() + hours * 3600000).toISOString());
      const changed = (await api.patch(`/tickets/${ticket.id}`, { priority: priority === 'low' ? 'urgent' : 'low' })).body;
      assert.equal(changed.due, ticket.due);
      assert.equal((await api.get(`/tickets/${ticket.id}`)).body.due, ticket.due);
    }
    assert.ok((await api.get('/tickets')).body.items.every(ticket => ticket.due));
  });
});

test('overdue uses strict time, active states, combined filters and cursor pages', async () => {
  const clock = manualClock();
  await withService({ clock, dueTimes: true }, async api => {
    for (let index = 0; index < 4; index++) await api.post('/tickets', ticketBody({ priority: 'urgent' }));
    await api.post('/tickets', ticketBody({ priority: 'low' }));
    await api.post('/tickets/T-0002/transition', { to: 'in_progress' });
    await api.post('/tickets/T-0003/transition', { to: 'in_progress' });
    await api.post('/tickets/T-0003/transition', { to: 'resolved' });
    await api.post('/tickets/T-0004/transition', { to: 'in_progress' });
    await api.post('/tickets/T-0004/transition', { to: 'resolved' });
    await api.post('/tickets/T-0004/transition', { to: 'closed' });
    clock.advance(4 * 3600000);
    assert.deepEqual((await api.get('/tickets?overdue=true')).body.items, []);
    clock.advance(1);
    const first = (await api.get('/tickets?overdue=true&limit=1')).body;
    assert.deepEqual(first.items.map(t => t.id), ['T-0001']);
    const second = (await api.get(`/tickets?overdue=true&limit=1&cursor=${first.next}`)).body;
    assert.deepEqual(second.items.map(t => t.id), ['T-0002']);
    assert.equal(second.next, null);
    assert.deepEqual((await api.get('/tickets?overdue=true&status=in_progress&priority=urgent')).body.items.map(t => t.id), ['T-0002']);
    assert.equal((await api.get('/tickets?overdue=false')).body.items.length, 5);
    assert.equal((await api.get('/tickets?overdue=yes')).status, 400);
  });
});

test('off keeps API behavior while saving due, and later enabling preserves original promises', async t => {
  const file = dataFile(t);
  const clock = manualClock();
  await withService({ clock, dataFile: file }, async api => {
    const ticket = (await api.post('/tickets', ticketBody({ priority: 'high' }))).body;
    assert.equal('due' in ticket, false);
    assert.equal('due' in (await api.patch('/tickets/T-0001', { priority: 'urgent' })).body, false);
    clock.advance(200 * 3600000);
    assert.equal((await api.get('/tickets?overdue=nonsense')).body.items.length, 1);
    assert.equal('due' in (await api.get('/tickets/T-0001')).body, false);
  });
  const document = JSON.parse(fs.readFileSync(file, 'utf8'));
  const due = document.tickets[0].due;
  assert.equal(due, '2025-09-02T08:00:00.000Z');
  assert.equal(document.version, 1);
  await withService({ clock, dataFile: file, dueTimes: true, dueHours: { ...DEFAULT_HOURS, high: 1, urgent: 2 } }, async api => {
    assert.equal((await api.get('/tickets/T-0001')).body.due, due);
    assert.equal((await api.get('/tickets?overdue=true')).body.items.length, 1);
    assert.equal((await api.post('/tickets', ticketBody({ priority: 'urgent' }))).body.due,
      new Date(clock.now().getTime() + 2 * 3600000).toISOString());
  });
});

test('legacy backfill saves before exposure, retains creation time and metadata, and survives restarts', t => {
  const file = dataFile(t);
  const clock = manualClock();
  const original = new TicketStore({ clock });
  original.createTicket(ticketBody({ priority: 'low' }), 'system');
  const document = toDocument(original.snapshot(), clock.now());
  delete document.tickets[0].due;
  fs.writeFileSync(file, JSON.stringify(document));
  clock.advance(500 * 3600000);
  const persistence = createPersistence(file, { clock });
  const migrated = TicketStore.open({ clock, persistence, dueTimes: true });
  const saved = JSON.parse(fs.readFileSync(file, 'utf8'));
  assert.equal(saved.tickets[0].due, '2025-09-08T08:00:00.000Z');
  for (const field of ['audit', 'outbox', 'nextNumber']) assert.deepEqual(saved[field], document[field]);
  assert.equal(migrated.get('T-0001').created, document.tickets[0].created);
  assert.equal(migrated.get('T-0001').updated, document.tickets[0].updated);
  assert.equal(TicketStore.open({ clock, persistence, dueTimes: true, dueHours: { ...DEFAULT_HOURS, low: 1 } }).get('T-0001').due, saved.tickets[0].due);
  assert.throws(() => TicketStore.open({ clock, persistence: { load: () => ({ ...original.snapshot(), tickets: document.tickets }), save: () => { throw new Error('disk full'); } }, dueTimes: true }), /disk full/);
});

test('saved due values are validated and imports inherit configured hours', async () => {
  const clock = manualClock();
  const store = new TicketStore({ clock });
  store.createTicket(ticketBody(), 'system');
  const document = toDocument(store.snapshot(), clock.now());
  for (const due of [null, 12, '', 'invalid']) {
    document.tickets[0].due = due;
    assert.throws(() => fromDocument(document, message => new Error(message)), /due is not a time/);
  }
  await withService({ clock, dueTimes: true, dueHours: { ...DEFAULT_HOURS, normal: 3 } }, async api => {
    assert.equal((await api.post('/tickets/import', { tickets: [ticketBody(), ticketBody()] })).status, 201);
    const items = (await api.get('/tickets')).body.items;
    assert.equal(items.length, 2);
    assert.ok(items.every(ticket => ticket.due === new Date(clock.now().getTime() + 3 * 3600000).toISOString()));
  });
});
